SELECT toJSONString(tuple((SELECT groupArray(tuple(table,name,type,comment)) FROM system.columns WHERE database='system' AND match(table,'^metric_log') AND name='CurrentMetric_MemoryTracking'), (SELECT groupArray(tuple(metric,description)) FROM system.metrics WHERE metric='MemoryTracking'))) AS payload LIMIT 1 SETTINGS max_threads=2,max_execution_time=15,timeout_before_checking_execution_speed=0,max_rows_to_read=100000;
